// THESIS: separate pending dispatch from active/completed work; a bottom prompt editor feeds a compact dual monitor.
function renderDispatch(){return `<main class="workspace">${menuHeader('双区调度')}<div class="desk dispatch-desk">${batchNav()}<section class="dispatch-center"><div class="split-monitor"><section class="panel"><div class="panel-head"><h2>等待派发</h2><span class="sub">9 项</span></div><div class="table-toolbar"><input type="search" data-search placeholder="搜索等待任务" aria-label="搜索提示词或模型"><small data-visible-count>9 个任务</small></div><div class="waiting-stack">${mockTasks.filter(t=>t.status==='等待中').map(t=>`<article class="wait-row ${t.id===4?'selected':''}" data-inspect="${t.id}" data-task="${t.id}" data-state="${t.status}" data-group="${t.batch}" tabindex="0"><div class="row"><span>#${String(t.id).padStart(2,'0')}　${t.model}</span><span class="state waiting">等待</span></div><p>${t.prompt}</p><small>提示词组 ${t.batch+1} · 抽奖 ${((t.id-1)%3)+1}/3</small></article>`).join('')}</div><div class="panel-footer"><button data-demo="将选中任务置顶">置顶</button><button data-demo="跳过等待任务">跳过</button><button data-demo="打乱等待任务">打乱</button></div></section><section class="panel"><div class="panel-head"><h2>当前 / 最近完成</h2><span class="sub">串行</span></div><div class="now-task"><div class="row spread"><span class="state running">当前生成 · 示意</span><small>#03</small></div><p>晨光里的橘猫</p><small>Qwen-Image 2.1 · INT8<br>切换模型不影响当前任务</small><div class="progress"><span></span></div><div class="row spread"><small>进度示意 45%</small><button data-demo="停止当前生成">停止当前</button></div></div><div class="recent-output"><figure><img src="../assets/flux2.png" alt="FLUX.2 1024 方图实际输出"><small>#01　FLUX.2<br>1024 × 1024</small></figure><figure><img src="../assets/qwen.png" alt="Qwen 768 方图实际输出"><small>#02　Qwen 2.1<br>768 × 768</small></figure></div><div class="panel-footer"><button data-demo="下载最近完成的作品">下载</button><button data-demo="导出全部作品">导出</button><button data-demo="收藏图片">收藏</button></div></section></div>${batchInput()}</section>${inspector('任务 04 · 等待中')}</div>${footer()}</main>`;}
